function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#051428', Blade='#d8dee8', BladeLt='#f5f7fa', Hilt='#8b4510', Gem='#e03050';
  // sword vertical
  px(28,6,8,36,O); px(29,7,6,34,Blade); px(29,7,6,2,BladeLt);
  px(30,8,2,30,BladeLt);
  // guard
  px(18,38,28,6,O); px(19,39,26,4,Hilt);
  // grip
  px(28,42,8,14,O); px(29,43,6,12,Hilt);
  px(30,46,4,2,Gem);

}
